import test from'node:test';import assert from'node:assert/strict';import{autoLingAutomaton,messyAutomaton,StateSpaceAssociationResolver,QualityTransferLedger,withQualityPorts}from'../src/index.mjs';
const configured=()=>{const a=withQualityPorts(autoLingAutomaton(),[{direction:'output',quality:'grammar',modes:['observe','borrow','learn','cultivate']},{direction:'input',quality:'simulation',modes:['borrow','learn']}]);const m=withQualityPorts(messyAutomaton(),[{direction:'input',quality:'grammar',modes:['borrow','learn','cultivate'],retention:'profile'},{direction:'output',quality:'simulation',modes:['observe','borrow','learn']}]);return{a,m,association:new StateSpaceAssociationResolver().resolve(a,m)};};
test('resonant tools selectively transfer compatible qualities',()=>{const{a,m,association}=configured(),ledger=new QualityTransferLedger();const event=ledger.transfer({source:a,target:m,quality:'grammar',mode:'learn',value:{rule:'x'},association});assert.equal(event.quality,'grammar');assert.equal(event.mode,'learn');assert.equal(event.association.operator,association.gateRelation.operator);});
test('quality transfer does not expose undeclared qualities',()=>{const{a,m,association}=configured(),ledger=new QualityTransferLedger();assert.throws(()=>ledger.transfer({source:a,target:m,quality:'memory',mode:'learn',value:{},association}),error=>error.code==='QUALITY_NOT_REACHABLE');});
test('borrowed or learned quality changes are reversible without changing source ownership',()=>{const{a,m,association}=configured(),ledger=new QualityTransferLedger();const event=ledger.transfer({source:m,target:a,quality:'simulation',mode:'borrow',value:{ticks:3},association});assert.equal(ledger.active.has(event.id),true);assert.equal(ledger.rollback(event.id,'context-ended'),true);assert.equal(ledger.active.has(event.id),false);assert.equal(m.id,'messy');});
